/* Klassenstufen als Zahlen, z. B. '5–10' wird zu 5,6,7,8,9,10 und '8/9' zu 8,9 */
function klassenVon(y){y=String(y||'');const r=y.match(/^(\d+)\s*[–-]\s*(\d+)$/);if(r){const a=[];for(let k=+r[1];k<=+r[2];k++)a.push(k);return a}return y.split('/').map(x=>parseInt(x,10)).filter(x=>!isNaN(x))}
function vorschauName(t){return t.toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,70)}
MATERIALS.forEach(m=>{Object.assign(m,MERKMALE[m.t]||{});m.k=klassenVon(m.year);m.fa=m.fa||Object.keys(FALLANLAESSE).filter(k=>FALLANLAESSE[k].m.some(p=>m.t.startsWith(p)));if(m.img)m.img='/assets/vorschau/'+vorschauName(m.t)+'.webp'});
function istNeu(m){if(!m.neu)return false;const d=new Date(m.neu+'T00:00:00');return (new Date()-d)/864e5<30}

